const assets={"/app.js":"import {evaluate,GestureGate} from './recognizer.js';\nconst $=id=>document.getElementById(id);let config=await(await fetch('/config.json')).json(),gate=new GestureGate(config.technique);\nlet stream,worker,ready=false,busy=false,running=false,session=0,lastFrame=-1,lastDispatch=0,stage='idle',countEnd=0,smooth=null,lastRaw=null,tracked=null,burst=0,debugBurst=false,clipURL=null,audioURL=null,audioContext,uploadedAudio;\nconst cam=$('camera'),canvas=$('effects'),ctx=canvas.getContext('2d');let latest={valid:false,usable:false,message:'No se detectan las manos'},latestGate={state:'ready',progress:0},fps=0;\nfunction hint(t){$('hint').textContent=t;}function state(t){$('state').textContent=t;}\nfunction resetPractice(){gate.reset();smooth=null;lastRaw=null;tracked=null;latest={valid:false,usable:false,message:'No se detectan las manos'};latestGate={state:'ready',progress:0};$('progress').value=0;$('percent').textContent='0%';}\nfunction stop(){session++;running=false;stream?.getTracks().forEach(t=>t.stop());stream=null;cam.srcObject=null;worker?.terminate();worker=null;ready=false;busy=false;stage='idle';resetPractice();$('empty').hidden=false;$('countdown').hidden=true;$('reference').pause();$('reference').hidden=true;$('start').disabled=false;$('practice').disabled=true;$('stop').disabled=true;state('ESPERA');hint('Cámara apagada.');$('fps').textContent='CÁMARA INACTIVA';}\n$('start').onclick=async()=>{const ticket=++session;$('start').disabled=true;hint('Solicitando cámara y preparando el seguimiento…');\n try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Abre la aplicación en HTTPS o localhost.');\n const acquired=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:960},height:{ideal:720},facingMode:'user'},audio:false});if(ticket!==session){acquired.getTracks().forEach(t=>t.stop());return;}stream=acquired;cam.srcObject=stream;await cam.play();canvas.width=cam.videoWidth;canvas.height=cam.videoHeight;$('viewport').style.aspectRatio=`${canvas.width}/${canvas.height}`;\n $('empty').hidden=true;$('stop').disabled=false;running=true;stage='loading';worker=new Worker('/tracker.js',{type:'module'});\n worker.onerror=e=>{hint('No se pudo cargar el motor de seguimiento. Revisa conexión y compatibilidad.');state('ERROR');$('practice').disabled=true;};\n worker.onmessage=({data})=>{\n if(data.type==='ready'){ready=true;stage='guide';$('practice').disabled=false;state('PREPARACIÓN');hint('Motor listo. Revisa la guía y empieza la práctica.');}\n if(data.type==='error'){busy=false;ready=false;$('practice').disabled=true;hint('Error del seguimiento: '+data.message);state('ERROR');}\n if(data.type==='result'){\n busy=false;if(!running)return;const t=performance.now();const raw=data.hands[0];\n if(raw){const jump=lastRaw&&Math.hypot(raw[0].x-lastRaw[0].x,raw[0].y-lastRaw[0].y)>.25;if(jump){smooth=null;gate.progress=0;gate.lastValid=null;}\n smooth=raw.map((p,i)=>smooth?{x:smooth[i].x*.4+p.x*.6,y:smooth[i].y*.4+p.y*.6,z:p.z}:p);tracked=smooth;lastRaw=raw;\n // Evaluate raw AND smoothed: smoothing must not prolong an old valid pose.\n const a=evaluate(raw,canvas.width,canvas.height,config.technique.gesture),b=evaluate(smooth,canvas.width,canvas.height,config.technique.gesture);latest={...b,valid:a.valid&&b.valid,usable:a.usable&&b.usable,message:a.valid?b.message:a.message};\n }else{tracked=null;smooth=null;lastRaw=null;latest={valid:false,usable:false,message:'No se detectan las manos'};}\n if(stage==='practice'){\n latestGate=gate.update(t,latest);hint(latestGate.message);state(({holding:'RECONOCIMIENTO',paused:'SEGUIMIENTO PERDIDO',cooldown:'ACTIVACIÓN',release:'REARMADO',ready:'PREPARACIÓN'})[latestGate.state]);\n $('progress').value=latestGate.progress;$('percent').textContent=Math.round(latestGate.progress*100)+'%';if(latestGate.fire)activate(false);\n }\n if($('debug').checked)$('metrics').textContent=JSON.stringify({stage,recognition:latest,gate:latestGate,model:'MediaPipe Hand Landmarker / CPU Worker',inferenceFPS:fps.toFixed(1)},null,2);\n }\n };\n worker.postMessage({type:'init'});\n }catch(e){stop();hint(e.name==='NotAllowedError'?'Permiso de cámara denegado. Puedes habilitarlo en el navegador.':e.name==='NotFoundError'?'No se encuentra una webcam.':e.message);state('ERROR');}\n};\n$('stop').onclick=stop;\n$('practice').onclick=()=>{if(!ready)return;$('reference').pause();$('reference').hidden=true;resetPractice();stage='countdown';countEnd=performance.now()+3000;$('countdown').hidden=false;hint('Coloca la mano completa frente a la cámara.');};\n$('replay').onclick=()=>{if(!clipURL)return;stage='reference';resetPractice();$('reference').hidden=false;$('reference').currentTime=0;$('reference').play().catch(()=>hint('Pulsa reproducir en el vídeo.'));};\n$('reference').onended=()=>{ $('reference').hidden=true;if(ready)$('practice').click();else hint('Referencia terminada. Activa la cámara para practicar.');};\n$('reference').onerror=()=>{hint('No se puede reproducir este formato. Prueba MP4 H.264 o continúa con la guía.');$('reference').hidden=true;stage=ready?'guide':'idle';};\n$('videoFile').onchange=e=>{const file=e.target.files[0];if(!file)return;if(clipURL)URL.revokeObjectURL(clipURL);clipURL=URL.createObjectURL(file);$('reference').src=clipURL;$('replay').disabled=false;$('resourceStatus').textContent='Vídeo de sesión: '+file.name;config.technique.video={source:'local-session',name:file.name};$('replay').click();};\n$('audioFile').onchange=e=>{const f=e.target.files[0];if(!f)return;if(audioURL)URL.revokeObjectURL(audioURL);audioURL=URL.createObjectURL(f);uploadedAudio=new Audio(audioURL);config.technique.audio={source:'local-session',name:f.name};$('resourceStatus').textContent='Audio de sesión: '+f.name;};\nfunction sound(){const volume=+$('volume').value;if(!volume)return;if(uploadedAudio){uploadedAudio.volume=volume;uploadedAudio.currentTime=0;uploadedAudio.play().catch(()=>hint('Audio no reproducible. La técnica visual sigue funcionando.'));return;}\n try{audioContext??=new AudioContext();audioContext.resume();const o=audioContext.createOscillator(),g=audioContext.createGain(),t=audioContext.currentTime;o.type='sine';o.frequency.setValueAtTime(170,t);o.frequency.exponentialRampToValueAtTime(45,t+.65);g.gain.setValueAtTime(volume*.3,t);g.gain.exponentialRampToValueAtTime(.001,t+.7);o.connect(g).connect(audioContext.destination);o.start();o.stop(t+.7);}catch{}}\nfunction activate(debug){burst=performance.now();debugBurst=debug;sound();if(debug)hint('Prueba de efectos · no es una detección de gesto');}\n$('debug').onchange=()=>{$('debugPanel').hidden=!$('debug').checked;};$('testEffect').onclick=()=>activate(true);\n$('hold').onchange=()=>{const n=+$('hold').value;if(Number.isFinite(n)&&n>=500&&n<=5000){config.technique.holdMs=n;gate=new GestureGate(config.technique);$('holdLabel').textContent=(n/1000).toFixed(1)+' s';}};\n$('exportConfig').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(config,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='jujutsu-config.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};\n$('importConfig').onchange=async e=>{try{const c=JSON.parse(await e.target.files[0].text());const v=c.technique,g=v.gesture;if(v.id!=='blue-adapted'||g.type!=='two-fingers')throw Error('Esta versión solo admite la técnica Azul adaptada.');for(const [k,min,max] of [['holdMs',500,5000],['lostGraceMs',0,500],['cooldownMs',1800,10000],['releaseMs',300,2000]])if(!Number.isFinite(v[k])||v[k]<min||v[k]>max)throw Error('Valor no válido: '+k);for(const [k,min,max] of [['extendedAngle',140,175],['foldedAngle',80,145],['minSeparation',.05,.5],['maxSeparation',.6,2],['minPalmPixels',30,150],['minPalmAspect',.15,.7]])if(!Number.isFinite(g[k])||g[k]<min||g[k]>max)throw Error('Umbral no válido: '+k);\n // Accept tuning only; never fetch resource paths from imported input.\n config.technique={...config.technique,gesture:{...g},holdMs:v.holdMs,lostGraceMs:v.lostGraceMs,cooldownMs:v.cooldownMs,releaseMs:v.releaseMs};gate=new GestureGate(config.technique);$('hold').value=v.holdMs;$('holdLabel').textContent=(v.holdMs/1000).toFixed(1)+' s';hint('Ajustes importados. Vuelve a seleccionar los recursos locales.');}catch(err){hint('Configuración rechazada: '+err.message);}};\n$('docs').onclick=async()=>{$('docBody').textContent=await(await fetch('/project.txt')).text();$('documentation').showModal();};$('closeDocs').onclick=()=>$('documentation').close();\n$('gojo').onclick=()=>hint('Gojo seleccionado. Técnica disponible: Azul adaptado.');$('blue').onclick=()=>hint(config.technique.instructions);\nfunction draw(now){requestAnimationFrame(draw);ctx.clearRect(0,0,canvas.width,canvas.height);if(document.hidden)return;\n if(stage==='countdown'){const n=Math.ceil((countEnd-now)/1000);$('countdown').textContent=n>0?n:'YA';if(n<=0){$('countdown').hidden=true;stage='practice';state('PREPARACIÓN');}}\n if(running&&ready&&!busy&&cam.readyState>=2&&cam.currentTime!==lastFrame&&now-lastDispatch>50){lastFrame=cam.currentTime;const delta=now-lastDispatch;lastDispatch=now;fps=1000/delta;$('fps').textContent=Math.round(fps)+' FPS · LOCAL';busy=true;const ticket=session;createImageBitmap(cam).then(frame=>{if(!running||ticket!==session){frame.close();return;}worker.postMessage({type:'frame',frame,t:now},[frame]);}).catch(()=>{busy=false;hint('No se pudo leer el fotograma de cámara.');});}\n if(!canvas.width)return;const w=canvas.width,h=canvas.height;const map=p=>({x:(1-p.x)*w,y:p.y*h});\n if(tracked&&$('debug').checked){ctx.fillStyle='#a8eeff';ctx.strokeStyle='#73e3ff88';for(const path of [[0,1,2,3,4],[0,5,6,7,8],[5,9,10,11,12],[9,13,14,15,16],[13,17,18,19,20],[0,17]]){ctx.beginPath();path.forEach((i,n)=>{const p=map(tracked[i]);n?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y);});ctx.stroke();}tracked.forEach(p=>{const q=map(p);ctx.beginPath();ctx.arc(q.x,q.y,3,0,Math.PI*2);ctx.fill();});}\n const elapsed=now-burst,active=burst>0&&elapsed<config.technique.effect.durationMs;const charging=stage==='practice'&&latestGate.progress>0;let center=tracked?map(tracked[9]):null;if(!center&&active&&debugBurst)center={x:w*.5,y:h*.5};\n if(center&&(charging||active)){const intensity=+$('intensity').value,progress=active?1:latestGate.progress,radius=(active?75:18+progress*30)*Math.min(w/800,1.3);const fade=active?1-elapsed/config.technique.effect.durationMs:1;ctx.save();ctx.globalAlpha=fade*intensity;ctx.globalCompositeOperation='screen';const g=ctx.createRadialGradient(center.x,center.y,0,center.x,center.y,radius*2);g.addColorStop(0,'#f1fbff');g.addColorStop(.15,'#8ae1ff');g.addColorStop(.45,'#206affaa');g.addColorStop(1,'#1849ff00');ctx.fillStyle=g;ctx.beginPath();ctx.arc(center.x,center.y,radius*2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#a4e4ff';ctx.lineWidth=1.5;for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(center.x,center.y,radius*(1+i*.35),radius*(.3+i*.12),now/700+i,0,Math.PI*2);ctx.stroke();}for(let i=0;i<24;i++){const a=i*2.4+now/1300,rad=radius*(1+(i%5)/4);ctx.fillStyle='#9edfff';ctx.fillRect(center.x+Math.cos(a)*rad,center.y+Math.sin(a)*rad,2,2);}if(active){ctx.strokeStyle='#5eafff';ctx.beginPath();ctx.arc(center.x,center.y,radius+elapsed*.15,0,Math.PI*2);ctx.stroke();if(!$('reduced').checked&&elapsed<100){ctx.globalAlpha=.12*intensity;ctx.fillStyle='#c2efff';ctx.fillRect(0,0,w,h);}}ctx.restore();}\n}\ncanvas.width=960;canvas.height=720;requestAnimationFrame(draw);\ndocument.addEventListener('visibilitychange',()=>{if(document.hidden){resetPractice();if(stage==='practice'||stage==='countdown'){stage='guide';$('countdown').hidden=true;hint('Práctica pausada. Pulsa Empezar práctica para continuar.');}}});\nwindow.addEventListener('pagehide',()=>{stop();if(clipURL)URL.revokeObjectURL(clipURL);if(audioURL)URL.revokeObjectURL(audioURL);});\n","/config.json":"{\"version\":1,\"character\":{\"id\":\"gojo\",\"name\":\"Satoru Gojo\",\"colors\":[\"#72dcff\",\"#a49bff\"]},\"technique\":{\"id\":\"blue-adapted\",\"name\":\"Azul\",\"canonStatus\":\"Adaptación jugable: no se afirma un sello original verificado\",\"video\":null,\"audio\":null,\"instructions\":\"Palma hacia la cámara. Extiende índice y corazón; flexiona anular y meñique. Pulgar libre. Mantén la mano completa visible.\",\"gesture\":{\"type\":\"two-fingers\",\"extendedAngle\":150,\"foldedAngle\":135,\"minSeparation\":0.12,\"maxSeparation\":1.5,\"minPalmPixels\":55,\"minPalmAspect\":0.3},\"holdMs\":1200,\"lostGraceMs\":250,\"releaseMs\":500,\"cooldownMs\":2200,\"effect\":{\"type\":\"blue-orb\",\"durationMs\":1800}}}\n","/index.html":"<!doctype html><html lang=\"es\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Jujutsu Gesture Lab</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body>\n<header><a class=\"brand\" href=\"/\">呪 <span>JUJUTSU<small>GESTURE LAB</small></span></a><span class=\"pill\">EXPERIMENTO 001 · VIDEO FX</span><button id=\"docs\">Guía del proyecto ↗</button></header>\n<main><section class=\"intro\"><div><p class=\"eyebrow\">ENTRENA. CONCENTRA. ACTIVA.</p><h1>La técnica está<br>en tus <em>manos.</em></h1><p>Tu cámara. Tu energía. Un gesto real.<br>Domina tu primera técnica en el laboratorio.</p></div><div class=\"sigil\" aria-hidden=\"true\"><div class=\"orb\"></div><span>無限</span></div></section>\n<div class=\"workspace\"><aside><p class=\"eyebrow\">01 / PERSONAJE</p><button class=\"character selected\" id=\"gojo\"><span class=\"avatar\">五</span><span><b>Satoru Gojo</b><small>EL HECHICERO MÁS FUERTE</small></span><span class=\"dot\"></span></button><p class=\"eyebrow\">02 / TÉCNICA</p><button class=\"technique selected\" id=\"blue\"><span>01</span><div><b>Azul</b><small>ATRACCIÓN · ADAPTACIÓN JUGABLE</small></div>↗</button><div class=\"locked\">Sukuna · Megumi · Yuji<small>Catálogo de ampliación · aún no jugables</small></div><hr><p class=\"eyebrow\">MODO DE ENTRENAMIENTO</p><div class=\"modes\"><b>Tutorial</b><span>Libre · Próximamente</span><span>Desafío · Próximamente</span></div><div class=\"privacy\"><i></i><div>Procesamiento local<small>Tu cámara no se graba ni se envía.</small></div></div></aside>\n<section class=\"stagepanel\"><div class=\"stagehead\"><div><small>GOJO / TÉCNICA 01</small><h2>Concentración: Azul</h2></div><span id=\"state\" class=\"pill\">ESPERA</span></div><div class=\"viewport\" id=\"viewport\"><video id=\"camera\" autoplay playsinline muted></video><canvas id=\"effects\"></canvas><div class=\"grid\"></div><div id=\"empty\"><span class=\"cameraIcon\">◎</span><h3>Encuentra tu energía</h3><p>Conecta tu webcam para comenzar.<br>El reconocimiento ocurre en tu navegador.</p><button id=\"start\" class=\"primary\">Activar cámara <span>↗</span></button><small>Se te pedirá permiso · sin micrófono</small></div><div id=\"countdown\" hidden></div><div class=\"viewtop\"><span>LOCAL VISION</span><span id=\"fps\">CÁMARA INACTIVA</span></div><div class=\"viewbottom\"><span id=\"hint\" role=\"status\" aria-live=\"polite\">Selecciona tu vídeo o comienza con la guía visual.</span><span>✦</span></div><video id=\"reference\" controls playsinline hidden></video></div>\n<div class=\"progressline\"><span id=\"progressLabel\">ENERGÍA ACUMULADA</span><b id=\"percent\">0%</b></div><progress id=\"progress\" max=\"1\" value=\"0\"></progress><div class=\"actions\"><button id=\"practice\" disabled class=\"primary\">Empezar práctica ↗</button><button id=\"replay\" disabled>Ver referencia</button><button id=\"stop\" disabled>Apagar cámara</button></div></section>\n<aside class=\"guide\"><p class=\"eyebrow\">EL GESTO / 1 MANO</p><div class=\"handguide\" aria-label=\"Índice y corazón extendidos\">✌</div><h3>Dos dedos.<br>Una intención.</h3><p>Palma hacia la cámara. Extiende índice y corazón. Flexiona anular y meñique; pulgar libre.</p><div class=\"stat\"><span>Mantén el gesto</span><b id=\"holdLabel\">1,2 s</b></div><div class=\"stat\"><span>Reconocimiento</span><b>Geométrico</b></div><p class=\"note\">Gesto adaptado para webcam. No representa un sello original verificado.</p><hr><label class=\"upload\">＋ Cargar vídeo local<input type=\"file\" id=\"videoFile\" accept=\"video/*\"></label><label class=\"upload\">♫ Cargar audio local<input type=\"file\" id=\"audioFile\" accept=\"audio/*\"></label><small id=\"resourceStatus\">Sin clip: se utilizará esta guía.</small></aside></div>\n<section class=\"settings\"><div><p class=\"eyebrow\">AJUSTA TU EXPERIENCIA</p><h3>Controla la intensidad.</h3></div><label>Volumen<input id=\"volume\" type=\"range\" min=\"0\" max=\"1\" step=\".05\" value=\".3\"></label><label>Energía visual<input id=\"intensity\" type=\"range\" min=\".2\" max=\"1\" step=\".1\" value=\".7\"></label><label class=\"check\"><input id=\"reduced\" type=\"checkbox\" checked> Reducir destellos</label><label class=\"check\"><input id=\"debug\" type=\"checkbox\"> Depuración</label></section>\n<details id=\"debugPanel\" hidden><summary>Laboratorio de reconocimiento</summary><label>Mantenimiento (ms) <input id=\"hold\" type=\"number\" min=\"500\" max=\"5000\" step=\"100\" value=\"1200\"></label><button id=\"testEffect\">Probar efecto · depuración, sin reconocimiento</button><button id=\"exportConfig\">Exportar configuración</button><label>Importar configuración<input id=\"importConfig\" type=\"file\" accept=\"application/json\"></label><pre id=\"metrics\">Sin detecciones</pre></details>\n<footer><span>JUJUTSU GESTURE LAB</span><span>Proyecto experimental de fans · Cámara + efectos 2D · Sin anclaje espacial</span><span>v0.1 / AZUL</span></footer></main>\n<dialog id=\"documentation\"><button id=\"closeDocs\">Cerrar ✕</button><article id=\"docBody\"></article></dialog><script type=\"module\" src=\"/app.js\"></script></body></html>\n","/project.txt":"JUJUTSU GESTURE LAB — Diseño y estado v0.1\n\n1. Experiencia\nEspejo de webcam con efectos 2D. No implementa realidad aumentada con anclaje espacial ni comprensión de la habitación. El reconocimiento sucede en un Worker del navegador. No hay grabación, telemetría de imágenes ni subida de vídeo. Se descargan el motor, WASM y modelo desde jsDelivr/Google; esta entrega requiere conexión inicial y no garantiza funcionamiento offline. Las fuentes tipográficas también se descargan. Los archivos que el usuario selecciona se leen mediante URL de objeto local y desaparecen al cerrar la sesión; la configuración exportada conserva nombres, nunca acceso persistente al disco.\n\n2. Ejemplo completo\nSeleccionar Gojo y Azul → cargar un clip propio → verlo con controles → al terminar, si la cámara está lista, cuenta atrás y práctica. También se puede saltar el clip e iniciar práctica con la guía. La referencia ocupa el escenario únicamente fuera del reconocimiento. En la práctica permanecen visibles cámara y guía lateral. Mantener índice y corazón extendidos y anular y meñique flexionados 1,2 s. Al alcanzar el umbral, esfera azul en el centro de la mano y sonido. Recuperación 2,2 s. Abrir la mano durante 0,5 s con seguimiento válido antes de rearmar. Repetir o volver a la referencia.\n\n3. Tecnología y compatibilidad\nWeb: MediaPipe Tasks Vision 0.10.22-rc.20250304 fijado para reproducibilidad, Hand Landmarker, Worker de módulo con CPU, Canvas 2D, getUserMedia y vídeo HTML. No se afirma que esa versión sea la más reciente. Objetivo: Chrome de escritorio moderno con webcam. Safari/Firefox figuran en el ejemplo oficial, pero esta combinación concreta con Worker requiere validación en cada navegador. Errores de modelo, cámara o formato se muestran. HTTPS o localhost y permiso de cámara obligatorios. El MVP solicita hasta 960×720 y limita los envíos a 20 fps, con un único fotograma en vuelo. No promete esa velocidad en todos los equipos.\nEscritorio: un envoltorio posterior facilita distribuir modelos y recursos y usar archivos sin conexión, pero añade instaladores y mantenimiento. No es necesario para validar un gesto. No se implementa WebXR.\nFuentes oficiales consultadas el 16/11/2026:\nhttps://developers.google.com/edge/mediapipe/solutions/vision/hand_landmarker/web_js\nhttps://github.com/google-ai-edge/mediapipe-samples/blob/main/examples/hand_landmarker/js/README.md\nhttps://developer.mozilla.org/en-US/docs/Web/API/MediaDevices/getUserMedia\n\n4. Catálogo candidato\nTODOS los gestos siguientes son adaptaciones jugables. No se han verificado sellos concretos del anime; los clips del usuario servirán para contrastarlos y registrar episodio/tiempo/fuente. Un nombre de técnica no demuestra la fidelidad de la postura propuesta.\nGojo / Azul / azul-blanco / dos dedos extendidos y dos flexionados / 1 mano / esfera y pulso grave / dificultad baja-media / MVP implementado en código.\nGojo / Rojo / rojo-blanco / índice y avance / 1 mano / onda e impacto / media: profundidad ambigua / futuro.\nGojo / Púrpura / violeta / acercar palmas desde posiciones separadas / 2 manos / convergencia y proyectil / media-alta: oclusión / futuro.\nSukuna / Corte / negro-rojo / barrido de palma / 1 mano / cortes de pantalla y golpe seco / media: trayectoria / futuro.\nMegumi / Sombras / índigo / aproximar manos abiertas / 2 manos / siluetas y humo / alta: entrelazado y oclusiones / futuro.\nYuji / Impacto / rojo-negro / abrir y cerrar puño / 1 mano / anillo y golpe / media: no identifica contacto ni puñetazo real / futuro.\nCada ficha tendrá video y audio propios. Inicialmente son null: no hay episodios descargados ni archivos inventados.\n\n5. Reconocimiento\n21 puntos por mano. Se evalúan ángulos 2D en articulaciones PIP y DIP, en coordenadas de píxel para corregir la relación de aspecto. Índice y corazón: PIP y DIP >150°. Anular y meñique: PIP <135°. El pulgar es libre. Separación entre puntas dividida por longitud muñeca-base del corazón: entre 0,12 y 1,5. Tolerancias iniciales, no universales: deben calibrarse con pruebas humanas.\nSe rechazan puntos fuera del margen del encuadre, palma menor de 55 píxeles y relación ancho/longitud de palma menor de 0,3. Esto limita posturas de perfil; no prueba orientación 3D. Media exponencial de puntos con peso 0,6 para la observación nueva. El gesto debe ser válido tanto en puntos crudos como suavizados. Salto de muñeca >25% de la imagen reinicia la carga y el suavizado; no constituye identificación de persona.\nTiempo real monotónico; máximo 100 ms acreditados por muestra. Una detección aislada no activa. Una postura visible incorrecta reinicia. Una pérdida de seguimiento pausa sin acumular hasta 250 ms; después reinicia. No se arrastra el tiempo de una pestaña oculta. La activación necesita soltar con seguimiento válido; una mano ausente no cuenta como liberación.\nNo se interpreta handedness para esta técnica: funciona con cualquiera de las manos y no depende de etiquetas izquierda/derecha. La cámara se refleja al mostrarla y el dibujo invierte x una vez; inferencia sobre imagen sin reflejar. Ambas superficies comparten proporción, sin recorte cover.\nCon una cámara, z estimada no es distancia métrica. No se puede garantizar contacto, dedos cruzados, orden de dedos en oclusiones ni orientación real. Dedos ocultos pueden producir puntos inferidos plausibles; no hay confianza por articulación expuesta aquí. No se deben mostrar correcciones de contacto ni certificar posturas ocultas. Se pide palma visible, luz frontal difusa y contraste. No se exige forzar articulaciones.\nFuturo: distancia entre manos normalizada por tamaño de palmas, vectores muñeca-dedo para orientación 2D y centros en regiones de imagen. Movimiento: historial de posiciones y velocidades normalizadas. Secuencias: máquina de estados con orden, ventana temporal y reinicio al incumplir. Asociar manos por continuidad e identidad antes de suavizarlas; no mezclar el índice del resultado entre manos.\nDepuración: esqueleto, ángulos, separación, tamaño de palma, estado y progreso; exportación/importación validada de umbrales y tiempos. Probar efecto es una función marcada de depuración y no puntúa reconocimiento.\n\n6. Efectos y accesibilidad\nPreparación: esfera y partículas cuya intensidad aumenta con la carga. Activación: esfera, órbitas y onda centradas en landmark 9, sonido propio o tono sintetizado. Al perder mano se oculta el efecto real; una prueba de depuración puede usar centro de pantalla. El efecto no se dibuja detrás del cuerpo ni se ancla al mundo. MVP sin segmentación: halos frontales y ondas. Futuro con segmentación: capas tras la silueta. Futuro espacial: WebXR/SLAM con plataformas y dispositivos compatibles, como proyecto separado.\nVolumen e intensidad ajustables. Reducir destellos viene activado y elimina el flash de pantalla; no se usa estroboscopia. Al terminar se desvanece durante 1,8 s. Reconocimiento y dibujo se mantienen separados.\n\n7. Arquitectura\nCámara (MediaStream, sin audio) → ImageBitmap → Worker de seguimiento → puntos → validación geométrica → GestureGate → eventos de efecto y sonido.\nInterfaz controla selección, tutorial, clip y cuenta atrás. Canvas dibuja sobre vídeo espejo. config.json separa personaje, técnica, instrucciones, gesto, tiempos y efecto. app.js orquesta estos módulos en esta primera entrega; en próximas fases se extraerán CameraController, ResourceManager y EffectEngine a archivos propios.\nServidor Worker Cloudflare: entrega archivos y herramientas MCP de solo lectura get_project_plan y get_technique_config. El servidor no recibe fotogramas ni puede encender la webcam desde el chat. La cámara requiere abrir la aplicación y autorizarla allí.\n\n8. Fases y criterios observables\nFase 1, tutorial: elegir personaje/técnica; reproducir clip local si existe; saltarlo sin bloqueo; cámara visible durante práctica; aviso ante clip incompatible.\nFase 2, seguimiento: puntos siguen la mano en espejo; mano ausente no carga; puño y palma abierta no activan; dos dedos correctos mantienen carga. Probar al menos cinco personas, dos iluminaciones y ambas manos. Estos ensayos humanos están pendientes.\nFase 3, activación: 1 fotograma no dispara; mantener 1,2 s activa una sola vez; postura mantenida no repite; pérdida >250 ms reinicia; abrir 0,5 s tras recuperación permite repetir. Pruebas automatizadas de máquina de estados y geometría con datos sintéticos, más ensayo real pendiente.\nFase 4, rendimiento: medir fps de inferencia y fluidez del dibujo en un PC con webcam. Objetivo orientativo: 15–20 inferencias/s a 960×720, sin cola creciente. No se ha medido en el equipo del usuario.\nFase 5, catálogo: reconocer dos manos con asociación estable, clips por técnica, modo libre con selección explícita para evitar colisiones y desafío con secuencias temporizadas. Aún no implementados.\n\n9. Estado y pasos de comprobación\nCódigo del MVP y herramientas MCP implementados. Recursos del anime no incluidos. Los tests sintéticos prueban reglas y estados, no precisión sobre manos reales. Para validar: abrir aplicación en Chrome, autorizar webcam, cargar vídeo opcional, practicar, abrir depuración, comprobar que el puño no carga y que el gesto adaptado activa una vez. Abrir mano y repetir. Probar bloqueo de permiso, apagar cámara y cambiar de pestaña. No declarar esta entrega calibrada hasta completar esos ensayos.\n","/recognizer.js":"export const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);\nexport function angle(a,b,c){const u={x:a.x-b.x,y:a.y-b.y},v={x:c.x-b.x,y:c.y-b.y};return Math.acos(Math.max(-1,Math.min(1,(u.x*v.x+u.y*v.y)/(Math.hypot(u.x,u.y)*Math.hypot(v.x,v.y)||1))))*180/Math.PI;}\nexport function evaluate(h,w,height,g){\n if(!h||h.length!==21||h.some(p=>!Number.isFinite(p.x)||!Number.isFinite(p.y)))return {valid:false,usable:false,message:'No se detectan las manos'};\n const p=h.map(v=>({x:v.x*w,y:v.y*height})); const palm=distance(p[0],p[9]);\n if(h.some(v=>v.x<.025||v.x>.975||v.y<.025||v.y>.975))return {valid:false,usable:false,message:'Coloca toda la mano dentro del encuadre'};\n if(palm<g.minPalmPixels)return {valid:false,usable:false,message:'Acerca un poco la mano a la cámara'};\n const aspect=distance(p[5],p[17])/palm;\n if(aspect<g.minPalmAspect)return {valid:false,usable:false,message:'Orienta la palma hacia la cámara'};\n const angles=[5,9,13,17].map(i=>angle(p[i],p[i+1],p[i+2]));\n const dips=[5,9].map(i=>angle(p[i+1],p[i+2],p[i+3]));\n const separation=distance(p[8],p[12])/palm;\n const extended=angles[0]>g.extendedAngle&&angles[1]>g.extendedAngle&&dips.every(a=>a>g.extendedAngle);\n const folded=angles[2]<g.foldedAngle&&angles[3]<g.foldedAngle;\n const spaced=separation>g.minSeparation&&separation<g.maxSeparation;\n let message=!extended?'Extiende índice y corazón':!folded?'Flexiona anular y meñique':!spaced?'Ajusta la separación de los dos dedos':'Mantén el gesto';\n return {valid:extended&&folded&&spaced,usable:true,message,angles,dips,separation,palmPixels:palm,aspect};\n}\nexport class GestureGate{\n constructor(c){this.c=c;this.reset();}\n reset(){this.state='ready';this.progress=0;this.last=null;this.lastValid=null;this.release=0;this.until=0;}\n update(t,r){\n const dt=this.last===null?0:Math.min(100,Math.max(0,t-this.last));this.last=t;\n if(this.lastValid!==null&&t-this.lastValid>this.c.lostGraceMs&&this.state==='ready')this.progress=0;\n if(this.state==='cooldown'){\n  if(t<this.until)return {state:'cooldown',progress:0,fire:false,message:'Técnica activada · recuperación'};\n  this.state='release';\n }\n if(this.state==='release'){\n  this.release=r.usable&&!r.valid?this.release+dt:0;\n  if(this.release>=this.c.releaseMs){this.state='ready';this.progress=0;this.lastValid=null;this.release=0;return {state:'ready',progress:0,fire:false,message:'Técnica preparada'};}\n  return {state:'release',progress:0,fire:false,message:'Abre la mano para volver a preparar'};\n }\n if(r.valid){this.lastValid=t;this.progress+=dt;}\n else if(r.usable){this.progress=0;this.lastValid=null;}\n if(this.progress>=this.c.holdMs){this.state='cooldown';this.until=t+this.c.cooldownMs;this.progress=0;return {state:'cooldown',progress:1,fire:true,message:'¡Azul!'};}\n return {state:r.valid?'holding':this.progress?'paused':'ready',progress:this.progress/this.c.holdMs,fire:false,message:r.message};\n }\n}\n","/style.css":"@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');\n:root{color-scheme:dark;--bg:#090c12;--line:#242b38;--muted:#8793a7;--blue:#8edbff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#e9eef7;font:14px 'DM Sans',sans-serif}button,input{font:inherit}button{cursor:pointer;border:1px solid var(--line);background:#131923;color:#dce6f6;border-radius:6px;padding:11px 15px}button:hover{border-color:#8edbff}button:disabled{opacity:.4;cursor:default}header{height:88px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding:0 5%}.brand{display:flex;gap:13px;align-items:center;text-decoration:none;color:white;font-size:30px}.brand span{font:700 15px 'Space Grotesk';letter-spacing:3px}.brand small{display:block;font-size:9px;color:var(--muted);letter-spacing:4px;margin-top:4px}.pill{font:10px 'Space Grotesk';letter-spacing:1.5px;border:1px solid #303b4e;padding:8px 12px;border-radius:30px;color:#b4c7df}main{max-width:1540px;margin:auto;padding:0 5%}.intro{display:flex;justify-content:space-between;align-items:center;padding:48px 0 40px}.eyebrow{font:10px 'Space Grotesk';letter-spacing:2px;color:var(--muted);margin:0 0 20px}h1{font:500 clamp(38px,4vw,62px)/1.05 'Space Grotesk';letter-spacing:-3px;margin:0 0 20px}h1 em{font-style:normal;color:var(--blue)}.intro p:not(.eyebrow){color:var(--muted);line-height:1.8;margin:0}.sigil{position:relative;width:240px;height:180px;display:grid;place-items:center;margin-right:6%}.sigil:before,.sigil:after{content:'';position:absolute;border:1px solid #39648266;border-radius:50%;width:160px;height:160px;transform:rotateX(50deg) rotateZ(-35deg)}.sigil:after{width:220px;height:220px;transform:rotateY(65deg) rotateZ(40deg)}.sigil span{font-size:44px;letter-spacing:10px;z-index:1;text-shadow:0 0 25px #5ab9ff}.orb{position:absolute;width:75px;height:75px;border-radius:50%;background:#90dcff;filter:blur(30px);opacity:.55}.workspace{display:grid;grid-template-columns:240px minmax(0,1fr) 220px;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:#0e131c}aside{padding:25px 20px}aside:first-child{border-right:1px solid var(--line)}.character{display:flex;width:100%;align-items:center;gap:12px;text-align:left;padding:13px 10px;margin-bottom:28px}.selected{border:1px solid #55738a;background:linear-gradient(110deg,#1e3040,#141d29)}.avatar{font-size:26px;color:var(--blue);border:1px solid #35546c;padding:4px 8px}.character b{font-size:13px}.character small,.technique small,.locked small{display:block;font-size:8px;letter-spacing:.7px;color:var(--muted);margin-top:7px}.dot{width:5px;height:5px;background:var(--blue);border-radius:50%;margin-left:auto}.technique{display:flex;gap:10px;align-items:center;text-align:left;width:100%}.technique>span{font-size:10px;color:var(--muted)}.technique b{font-size:18px}.locked{margin:20px 0 30px;color:#778297;font-size:11px}.modes{display:flex;flex-direction:column;gap:15px;font-size:12px}.modes b{color:var(--blue)}.modes span{color:#626e82}.privacy{margin-top:40px;display:flex;gap:9px;font-size:11px;color:#a7bfce}.privacy i{width:6px;height:6px;background:#9de6b8;border-radius:50%;margin-top:4px}.privacy small{display:block;color:var(--muted);font-size:9px;margin-top:6px}hr{border:0;border-top:1px solid var(--line);margin:25px 0}.stagepanel{padding:24px;min-width:0}.stagehead{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:20px}.stagehead small{font:9px 'Space Grotesk';letter-spacing:1.5px;color:var(--muted)}h2{font:500 21px 'Space Grotesk';margin:7px 0 0}.viewport{aspect-ratio:4/3;position:relative;overflow:hidden;background:radial-gradient(ellipse at 50% 70%,#152435,#090e17 65%);border:1px solid var(--line);border-radius:7px}.viewport>video#camera,.viewport>canvas{position:absolute;width:100%;height:100%;object-fit:contain;z-index:1}.viewport>video#camera{transform:scaleX(-1)}#effects{z-index:2;pointer-events:none}.grid{position:absolute;inset:0;background-image:linear-gradient(#6ba2db06 1px,transparent 1px),linear-gradient(90deg,#6ba2db06 1px,transparent 1px);background-size:35px 35px;pointer-events:none}.viewtop,.viewbottom{position:absolute;left:17px;right:17px;display:flex;justify-content:space-between;gap:10px;z-index:4;font:9px 'Space Grotesk';letter-spacing:1px;color:#92a8c0}.viewtop{top:16px}.viewbottom{bottom:14px;padding:12px;background:#0b111dd9;border:1px solid #24344a;border-radius:5px;font-size:11px;letter-spacing:0}.viewbottom span:last-child{color:var(--blue)}#empty{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;z-index:3;text-align:center}#empty[hidden]{display:none}.cameraIcon{border:1px solid #2e4a64;border-radius:50%;padding:10px 18px;font-size:38px;color:#8edbff}h3{font:500 20px 'Space Grotesk';margin:18px 0 8px}#empty p{color:var(--muted);font-size:12px;line-height:1.7;margin:0 0 20px}#empty small{font-size:9px;color:var(--muted);margin-top:12px}.primary{background:#b6e5ff;color:#102332;border-color:#b6e5ff;font-weight:600}.primary span{margin-left:20px}#countdown{position:absolute;inset:0;place-items:center;background:#07101c77;z-index:5;font:700 80px 'Space Grotesk';color:white}#countdown:not([hidden]){display:grid}#reference{position:absolute;inset:0;width:100%;height:100%;z-index:8;background:#080a0f;object-fit:contain}.progressline{display:flex;justify-content:space-between;margin:20px 0 9px;font:9px 'Space Grotesk';letter-spacing:1px;color:var(--muted)}.progressline b{color:var(--blue)}progress{width:100%;height:4px;border:0;background:#243044;border-radius:3px}progress::-webkit-progress-bar{background:#243044}progress::-webkit-progress-value{background:var(--blue)}.actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:18px}.actions button{font-size:11px;padding:10px 12px}.guide{border-left:1px solid var(--line)}.handguide{height:115px;display:grid;place-items:center;font-size:75px;color:#b2deff;background:radial-gradient(#273c5266,transparent 70%);filter:grayscale(1)}.guide h3{font-size:22px}.guide p{font-size:11px;line-height:1.8;color:var(--muted)}.stat{display:flex;justify-content:space-between;gap:8px;font-size:9px;border-top:1px solid var(--line);padding:13px 0;color:var(--muted)}.stat b{color:#c2d5eb}.guide p.note{font-size:9px}.upload{display:block;padding:10px;border:1px dashed #344255;border-radius:5px;font-size:10px;cursor:pointer;margin-top:8px}.upload input{display:none}#resourceStatus{display:block;font-size:9px;color:var(--muted);margin-top:12px;line-height:1.6}.settings{display:flex;align-items:center;gap:35px;border:1px solid var(--line);border-radius:8px;margin-top:22px;padding:20px 24px}.settings .eyebrow{margin:0;font-size:8px}.settings h3{margin:7px 0 0;font-size:17px}.settings label{display:flex;flex-direction:column;gap:10px;font-size:10px;color:#a4b1c4}input[type=range]{width:115px;accent-color:#a3ddff}.settings label.check{flex-direction:row;align-items:center;margin-left:auto}input[type=checkbox]{accent-color:#8edbff}footer{display:flex;justify-content:space-between;gap:20px;padding:28px 0;color:#607088;font-size:8px;letter-spacing:1px}details{padding:20px;border:1px solid var(--line);margin-top:15px}pre{white-space:pre-wrap;color:#a6dfff;font-size:11px}dialog{max-width:850px;width:90%;max-height:85vh;background:#111824;color:#dce6f4;border:1px solid #466078;border-radius:10px;padding:30px}dialog::backdrop{background:#000a}dialog article{white-space:pre-wrap;line-height:1.8;font-size:13px}dialog button{float:right}@media(min-width:1600px){.workspace{grid-template-columns:260px minmax(0,1fr) 240px}}@media(max-width:1100px){.workspace{grid-template-columns:190px minmax(0,1fr)}.guide{grid-column:1/-1;border-left:0;border-top:1px solid var(--line);display:block}.guide .handguide{float:left;width:160px}.guide hr{margin:12px 0}.guide .stat{display:inline-flex;margin-right:20px;gap:30px}.settings{flex-wrap:wrap;gap:20px}.guide .upload{display:inline-block;margin-right:10px}}@media(max-width:700px){header{height:70px}header>.pill{display:none}header button{font-size:10px}.intro{padding-top:30px}.sigil{display:none}.workspace{display:block}.workspace>aside:first-child{border-right:0;border-bottom:1px solid var(--line)}.character{margin-bottom:15px}.locked,.modes,.privacy,aside:first-child>hr{display:none}.stagepanel{padding:15px}.stagehead h2{font-size:17px}.stagehead .pill{font-size:8px}.settings label.check{margin-left:0}footer{flex-wrap:wrap}h1{letter-spacing:-2px}#empty h3{font-size:18px}#empty p{font-size:10px}#empty small{display:none}.cameraIcon{font-size:25px;padding:3px 12px}}\n","/tracker.js":"import {FilesetResolver,HandLandmarker} from 'https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.22-rc.20250304/vision_bundle.mjs';\nlet detector;\nself.onmessage=async({data})=>{\n try{\n if(data.type==='init'){\n const files=await FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.22-rc.20250304/wasm');\n detector=await HandLandmarker.createFromOptions(files,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task',delegate:'CPU'},runningMode:'VIDEO',numHands:1,minHandDetectionConfidence:.65,minHandPresenceConfidence:.65,minTrackingConfidence:.65});\n self.postMessage({type:'ready'});\n }else if(data.type==='frame'){\n try{const r=detector.detectForVideo(data.frame,data.t);self.postMessage({type:'result',t:data.t,hands:r.landmarks});}finally{data.frame.close();}\n }\n }catch(e){self.postMessage({type:'error',message:e.message});}\n};\n","/":"<!doctype html><html lang=\"es\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Jujutsu Gesture Lab</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body>\n<header><a class=\"brand\" href=\"/\">呪 <span>JUJUTSU<small>GESTURE LAB</small></span></a><span class=\"pill\">EXPERIMENTO 001 · VIDEO FX</span><button id=\"docs\">Guía del proyecto ↗</button></header>\n<main><section class=\"intro\"><div><p class=\"eyebrow\">ENTRENA. CONCENTRA. ACTIVA.</p><h1>La técnica está<br>en tus <em>manos.</em></h1><p>Tu cámara. Tu energía. Un gesto real.<br>Domina tu primera técnica en el laboratorio.</p></div><div class=\"sigil\" aria-hidden=\"true\"><div class=\"orb\"></div><span>無限</span></div></section>\n<div class=\"workspace\"><aside><p class=\"eyebrow\">01 / PERSONAJE</p><button class=\"character selected\" id=\"gojo\"><span class=\"avatar\">五</span><span><b>Satoru Gojo</b><small>EL HECHICERO MÁS FUERTE</small></span><span class=\"dot\"></span></button><p class=\"eyebrow\">02 / TÉCNICA</p><button class=\"technique selected\" id=\"blue\"><span>01</span><div><b>Azul</b><small>ATRACCIÓN · ADAPTACIÓN JUGABLE</small></div>↗</button><div class=\"locked\">Sukuna · Megumi · Yuji<small>Catálogo de ampliación · aún no jugables</small></div><hr><p class=\"eyebrow\">MODO DE ENTRENAMIENTO</p><div class=\"modes\"><b>Tutorial</b><span>Libre · Próximamente</span><span>Desafío · Próximamente</span></div><div class=\"privacy\"><i></i><div>Procesamiento local<small>Tu cámara no se graba ni se envía.</small></div></div></aside>\n<section class=\"stagepanel\"><div class=\"stagehead\"><div><small>GOJO / TÉCNICA 01</small><h2>Concentración: Azul</h2></div><span id=\"state\" class=\"pill\">ESPERA</span></div><div class=\"viewport\" id=\"viewport\"><video id=\"camera\" autoplay playsinline muted></video><canvas id=\"effects\"></canvas><div class=\"grid\"></div><div id=\"empty\"><span class=\"cameraIcon\">◎</span><h3>Encuentra tu energía</h3><p>Conecta tu webcam para comenzar.<br>El reconocimiento ocurre en tu navegador.</p><button id=\"start\" class=\"primary\">Activar cámara <span>↗</span></button><small>Se te pedirá permiso · sin micrófono</small></div><div id=\"countdown\" hidden></div><div class=\"viewtop\"><span>LOCAL VISION</span><span id=\"fps\">CÁMARA INACTIVA</span></div><div class=\"viewbottom\"><span id=\"hint\" role=\"status\" aria-live=\"polite\">Selecciona tu vídeo o comienza con la guía visual.</span><span>✦</span></div><video id=\"reference\" controls playsinline hidden></video></div>\n<div class=\"progressline\"><span id=\"progressLabel\">ENERGÍA ACUMULADA</span><b id=\"percent\">0%</b></div><progress id=\"progress\" max=\"1\" value=\"0\"></progress><div class=\"actions\"><button id=\"practice\" disabled class=\"primary\">Empezar práctica ↗</button><button id=\"replay\" disabled>Ver referencia</button><button id=\"stop\" disabled>Apagar cámara</button></div></section>\n<aside class=\"guide\"><p class=\"eyebrow\">EL GESTO / 1 MANO</p><div class=\"handguide\" aria-label=\"Índice y corazón extendidos\">✌</div><h3>Dos dedos.<br>Una intención.</h3><p>Palma hacia la cámara. Extiende índice y corazón. Flexiona anular y meñique; pulgar libre.</p><div class=\"stat\"><span>Mantén el gesto</span><b id=\"holdLabel\">1,2 s</b></div><div class=\"stat\"><span>Reconocimiento</span><b>Geométrico</b></div><p class=\"note\">Gesto adaptado para webcam. No representa un sello original verificado.</p><hr><label class=\"upload\">＋ Cargar vídeo local<input type=\"file\" id=\"videoFile\" accept=\"video/*\"></label><label class=\"upload\">♫ Cargar audio local<input type=\"file\" id=\"audioFile\" accept=\"audio/*\"></label><small id=\"resourceStatus\">Sin clip: se utilizará esta guía.</small></aside></div>\n<section class=\"settings\"><div><p class=\"eyebrow\">AJUSTA TU EXPERIENCIA</p><h3>Controla la intensidad.</h3></div><label>Volumen<input id=\"volume\" type=\"range\" min=\"0\" max=\"1\" step=\".05\" value=\".3\"></label><label>Energía visual<input id=\"intensity\" type=\"range\" min=\".2\" max=\"1\" step=\".1\" value=\".7\"></label><label class=\"check\"><input id=\"reduced\" type=\"checkbox\" checked> Reducir destellos</label><label class=\"check\"><input id=\"debug\" type=\"checkbox\"> Depuración</label></section>\n<details id=\"debugPanel\" hidden><summary>Laboratorio de reconocimiento</summary><label>Mantenimiento (ms) <input id=\"hold\" type=\"number\" min=\"500\" max=\"5000\" step=\"100\" value=\"1200\"></label><button id=\"testEffect\">Probar efecto · depuración, sin reconocimiento</button><button id=\"exportConfig\">Exportar configuración</button><label>Importar configuración<input id=\"importConfig\" type=\"file\" accept=\"application/json\"></label><pre id=\"metrics\">Sin detecciones</pre></details>\n<footer><span>JUJUTSU GESTURE LAB</span><span>Proyecto experimental de fans · Cámara + efectos 2D · Sin anclaje espacial</span><span>v0.1 / AZUL</span></footer></main>\n<dialog id=\"documentation\"><button id=\"closeDocs\">Cerrar ✕</button><article id=\"docBody\"></article></dialog><script type=\"module\" src=\"/app.js\"></script></body></html>\n"};
const tools=[{name:'get_project_plan',description:'Consulta el diseño, alcance, arquitectura, limitaciones y pruebas pendientes de Jujutsu Gesture Lab. Usa este contexto al ayudar a desarrollar la experiencia. No afirma validación humana ni sellos canónicos verificados.',inputSchema:{type:'object',properties:{},additionalProperties:false}},{name:'get_technique_config',description:'Obtiene la configuración vigente de Azul de Gojo, una adaptación jugable de dos dedos para webcam. No opera la cámara: el usuario debe abrir la aplicación. Recursos locales aportados por el usuario, sin descargas de episodios.',inputSchema:{type:'object',properties:{},additionalProperties:false}}];
const json=(v,status=200)=>new Response(JSON.stringify(v),{status,headers:{'content-type':'application/json'}});
export default {async fetch(req){const path=new URL(req.url).pathname;
 if(path==='/mcp'){
 if(req.method!=='POST')return new Response('Use POST',{status:405,headers:{Allow:'POST'}});
 let r;try{r=await req.json();}catch{return json({jsonrpc:'2.0',id:null,error:{code:-32700,message:'Parse error'}});}
 if(r.id===undefined)return new Response(null,{status:204});
 let result;
 if(r.method==='server/discover')result={supportedVersions:['2026-07-28'],capabilities:{tools:{}}};
 else if(r.method==='initialize')result={protocolVersion:'2024-11-05',capabilities:{tools:{}},serverInfo:{name:'jujutsu-gesture-lab',version:'0.1.0'}};
 else if(r.method==='ping')result={};
 else if(r.method==='tools/list')result={tools};
 else if(r.method==='tools/call'){
 const name=r.params?.name;if(!tools.some(t=>t.name===name))result={isError:true,content:[{type:'text',text:'Herramienta desconocida'}]};else result={content:[{type:'text',text:assets[name==='get_project_plan'?'/project.txt':'/config.json']}]};
 }else return json({jsonrpc:'2.0',id:r.id,error:{code:-32601,message:'Method not found'}});
 return json({jsonrpc:'2.0',id:r.id,result});
 }
 const body=assets[path];if(body===undefined)return new Response('Not found',{status:404});
 const type=path.endsWith('.js')?'text/javascript':path.endsWith('.css')?'text/css':path.endsWith('.json')?'application/json':path.endsWith('.txt')?'text/plain':'text/html';return new Response(body,{headers:{'content-type':type+'; charset=utf-8','x-content-type-options':'nosniff','permissions-policy':'camera=(self), microphone=()','cache-control':'no-cache'}});
}};
